<script setup>import {onMounted,ref} from 'vue';const users=ref([]);onMounted(async()=>{users.value=(await (await fetch('/api/admin/users',{credentials:'same-origin',headers:{Accept:'application/json'}})).json()).data});</script><template><v-container class="py-10"><div class="section-kicker">ADMINISTRAÇÃO</div><h1 class="text-h4 font-weight-bold mb-6">Usuários do sistema</h1><v-card rounded="xl"><v-table><thead><tr><th>Nome</th><th>E-mail</th><th>Localidade</th><th>Cargos</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.name}}</td><td>{{user.email}}</td><td>{{user.city?`${user.city} - ${user.state||''}`:'Não informado'}}</td><td><v-chip v-for="role in user.roles" :key="role.id" size="small" class="mr-1">{{role.label}}</v-chip></td></tr></tbody></v-table></v-card></v-container></template>
